items.copy:
$names = 'agy','codex','claude'
$guess = @{
  agy    = @("$env:LOCALAPPDATA\agy\bin")
  codex  = @("$env:LOCALAPPDATA\Programs\OpenAI\Codex\bin", "$env:USERPROFILE\.codex\bin")
  claude = @("$env:USERPROFILE\.local\bin")
}
$roots = @(@($env:LOCALAPPDATA, $env:APPDATA, $env:USERPROFILE) | Where-Object { $_ -and (Test-Path $_) } | Select-Object -Unique)
$where = @{}
foreach ($n in $names) {
  $dir = $null
  $pre = Get-Command $n -ErrorAction SilentlyContinue
  if ($pre -and $pre.Source) { $dir = Split-Path $pre.Source -Parent }
  if (-not $dir) { foreach ($g in $guess[$n]) { if (Test-Path (Join-Path $g "$n.exe")) { $dir = $g; break } } }
  if (-not $dir) {
    foreach ($r in $roots) {
      $hit = Get-ChildItem -Path $r -Filter "$n.exe" -Recurse -File -Depth 5 -ErrorAction SilentlyContinue | Select-Object -First 1
      if ($hit) { $dir = $hit.DirectoryName; break }
    }
  }
  if ($dir) { $where[$n] = $dir }
}
$found = @($where.Values | Select-Object -Unique)
if ($found.Count -gt 0) {
  $have = @([Environment]::GetEnvironmentVariable('Path','User') -split ';' | Where-Object { $_ })
  $new  = @($found | Where-Object { $have -notcontains $_ })
  if ($new.Count -gt 0) { [Environment]::SetEnvironmentVariable('Path', (($have + $new) -join ';'), 'User') }
  $cur = @($env:Path -split ';' | Where-Object { $_ })
  $now = @($found | Where-Object { $cur -notcontains $_ })
  if ($now.Count -gt 0) { $env:Path = (($cur + $now) -join ';') }
}
Write-Host ""
Write-Host "  ────────────────────────────────────────────────────────────"
$ok = 0
foreach ($n in $names) {
  if (-not $where.ContainsKey($n)) {
    Write-Host "   [ ] " -NoNewline -ForegroundColor Red
    Write-Host ("{0,-8}" -f $n) -NoNewline -ForegroundColor Red
    Write-Host "아직 설치되지 않았습니다" -ForegroundColor Red
    continue
  }
  $exe = Join-Path $where[$n] "$n.exe"
  $ver = $null
  try { $ver = (& $exe --version 2>&1 | Select-Object -First 1) } catch { $ver = $null }
  if ($ver) { $ver = ($ver -replace '\s+', ' ').Trim() }
  $byName = [bool](Get-Command $n -ErrorAction SilentlyContinue)
  if ($ver -and $byName) {
    Write-Host "   [v] " -NoNewline -ForegroundColor Green
    Write-Host ("{0,-8}" -f $n) -NoNewline -ForegroundColor Green
    Write-Host ("사용 가능!  " + $ver) -ForegroundColor Green
    $ok++
  } elseif ($ver) {
    Write-Host "   [!] " -NoNewline -ForegroundColor Yellow
    Write-Host ("{0,-8}" -f $n) -NoNewline -ForegroundColor Yellow
    Write-Host ($ver + "  — 설치는 됐지만 이 터미널이 아직 이름으로 못 찾습니다") -ForegroundColor Yellow
  } else {
    Write-Host "   [!] " -NoNewline -ForegroundColor Yellow
    Write-Host ("{0,-8}" -f $n) -NoNewline -ForegroundColor Yellow
    Write-Host "파일은 있는데 실행이 안 됩니다 — 설치를 다시 하세요" -ForegroundColor Yellow
  }
}
Write-Host "  ────────────────────────────────────────────────────────────"
if ($ok -eq 3) {
  Write-Host "   세 개 다 버전이 찍혔습니다. VS Code 껐다 켤 필요 없습니다." -ForegroundColor Cyan
} else {
  Write-Host ("   " + $ok + "/3 확인됨. [!] 는 새 터미널을 열면 대개 해결됩니다.") -ForegroundColor Yellow
}
Write-Host ""

